@@ -0,0 +1,44 @@
+@model Umbraco.Bench.Umbraco.Models.Blocks.PostListModel
+<section>
+    @if (!string.IsNullOrWhiteSpace(Model.Heading))
+    {
+        <h2 class="mb-8 text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
+    }
+    @if (Model.Posts.Count == 0)
+    {
+        <p class="text-slate-500">No posts yet.</p>
+    }
+    else
+    {
+        <ul class="grid gap-8 sm:grid-cols-2">
+            @foreach (var post in Model.Posts)
+            {
+                <li class="group overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition hover:shadow-lg">
+                    <a href="@post.Url" class="block">
+                        @if (!string.IsNullOrEmpty(post.ImageUrl))
+                        {
+                            <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" loading="lazy" />
+                        }
+                        <div class="p-6">
+                            <p class="text-xs font-semibold uppercase tracking-wide text-indigo-600">
+                                @if (post.PublishDate is { } date)
+                                {
+                                    <time datetime="@date.ToString("yyyy-MM-dd")">@date.ToString("d MMMM yyyy")</time>
+                                }
+                                @if (!string.IsNullOrWhiteSpace(post.Author))
+                                {
+                                    <span> &middot; @post.Author</span>
+                                }
+                            </p>
+                            <h3 class="mt-2 text-xl font-bold text-slate-900 group-hover:text-indigo-700">@post.Title</h3>
+                            @if (!string.IsNullOrWhiteSpace(post.Summary))
+                            {
+                                <p class="mt-3 text-slate-600">@post.Summary</p>
+                            }
+                        </div>
+                    </a>
+                </li>
+            }
+        </ul>
+    }
+</section>
